function icon(name,cls=""){return '<svg class="'+cls+'" viewBox="0 0 24 24" aria-hidden="true">'+(ICON_PATHS[name]||ICON_PATHS.disc)+'</svg>'}
function esc(s){return String(s===undefined?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function artist(id){return artists.find(x=>x.id===id)||artists[0]}
function track(id){return tracks.find(x=>x.id===id)||tracks[0]}
function cssvars(a){return `style="--a:${a.a};--b:${a.b};--c:${a.c}"`}
function cover(x,small=false){const a=typeof x==="string"?artist(x):x;return `<div class="cover${small?" cover--small":""}" ${cssvars(a)}><span class="cover-top"><span>HIDDEN / ${esc(a.code)}</span><span>SC.</span></span><span class="cover-bottom"><span>${esc(a.name)}</span><i>VOL.26</i></span></div>`}
function avatar(a,size=""){return `<div class="avatar ${size}" ${cssvars(a)}><span>${esc(a.name.split(" ").map(p=>p[0]).join("").slice(0,2))}</span></div>`}
function btn(label,action,cl=""){return `<button class="btn ${cl}" data-action="${esc(action)}">${label}</button>`}
function link(label,route,cl=""){return `<button class="btn ${cl}" data-route="${esc(route)}">${label}</button>`}
function fmtTime(t){const x=Math.max(0,Math.floor(Number(t)||0));return Math.floor(x/60)+":"+String(x%60).padStart(2,"0")}
function fmtNum(n){return n>=1000?(n/1000).toFixed(1)+"k":String(n)}
function hashSeed(str){return [...str].reduce((n,c)=>((n*31+c.charCodeAt(0))|0),1337)}
function wave(id,count=27){let s=Math.abs(hashSeed(id)),bars="";for(let j=0;j<count;j++){s=(s*1664525+1013904223)>>>0;let h=5+(s%24);bars+=`<span class="wavebar" style="height:${h}px"></span>`}return '<div class="waveform" aria-hidden="true">'+bars+"</div>"}
function stateDefault(){return {liked:[],saved:[],following:[],shares:[],heard:{},badge:false,trackId:"signal-live",volume:50,shuffle:false,repeat:false,submitted:[],recent:[]}}
function load(){try{const v=JSON.parse(localStorage.getItem("hs_soundcloud_v1"));return {...stateDefault(),...(v&&typeof v==="object"?v:{}),heard:{...((v&&v.heard)||{})}}}catch{return stateDefault()}}
let state=load();
const ui={genre:"all",mood:"night",dropIndex:0,modal:null,modalData:null,playing:false,currentTime:0,searchOpen:false,searchValue:"",toastTimer:null,lastTimestamp:0,lastCount:-1};
const $=s=>document.querySelector(s);
function persist(){try{localStorage.setItem("hs_soundcloud_v1",JSON.stringify(state))}catch{}}
function listHas(k,id){return Array.isArray(state[k])&&state[k].includes(id)}
function toggleList(k,id){if(!Array.isArray(state[k]))state[k]=[];state[k]=state[k].includes(id)?state[k].filter(x=>x!==id):[...state[k],id];persist()}
function routeNow(){return decodeURIComponent(location.hash.replace(/^#\/?/,"")||"discover")}
function currentView(){return routeNow().split("?")[0]}
function goto(route){const next="#/"+route;if(location.hash===next){render(true);return}location.hash=next}
function toast(message){const z=$("#toast");if(!z)return;z.textContent=message;z.classList.add("show");clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>z.classList.remove("show"),2800)}
function firstListen(){return Object.values(state.heard).some(s=>Number(s)>=8)}
function earnedSteps(){return [firstListen(),state.following.length>0,state.shares.length>0]}
function claimBadge(){if(state.badge)return;const st=earnedSteps();if(st.every(Boolean)){state.badge=true;persist();toast("First Listener 배지를 획득했어요!");renderKeep()}}
function missionPct(){return earnedSteps().filter(Boolean).length/3*100}
function pageHead(kicker,title,sub,extra=""){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1 style="font-size:clamp(36px,4vw,57px);margin:13px 0 12px">${title}</h1>${sub?`<p class="subcopy">${sub}</p>`:""}</div>${extra}</div>`}
function sectionHead(title,sub,route="",label="전체 보기"){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:""}</div>${route?`<button class="link-btn" data-route="${route}">${label} ${icon("arrow-up-right")}</button>`:""}</div>`}
function artistCard(a,index){const followed=listHas("following",a.id);return `<article class="artist-card"><button aria-label="${esc(a.name)} 프로필" data-route="artist/${a.id}" style="padding:0;display:block;width:100%;background:none;border:0;text-align:left;color:inherit"><div class="artist-cover">${cover(a)}</div></button><div class="artist-card-body"><div class="card-overline">0${index+1} / ${esc(a.tag)}</div><button data-route="artist/${a.id}" class="track-title" style="font-size:17px;text-align:left;border:0;background:transparent;padding:0;margin:7px 0 5px;max-width:100%">${esc(a.name)}</button><p>${esc(a.genre)}</p><div class="card-bottom"><button class="follow-mini ${followed?"following":""}" data-action="follow" data-id="${a.id}">${followed?icon("check")+" Following":icon("plus")+" Follow"}</button><button class="circle-play" data-action="play" data-id="${a.tracks[0]}" aria-label="${esc(a.name)} 트랙 재생">${icon("play")}</button></div></div></article>`}
function trackRow(t,i){const a=artist(t.artist),liked=listHas("liked",t.id),saved=listHas("saved",t.id),active=state.trackId===t.id;return `<div class="track-row ${active?"active":""}"><span class="track-index">${String(i+1).padStart(2,"0")}</span><button class="track-cover" aria-label="${esc(t.title)} 재생" data-action="play" data-id="${t.id}">${cover(a,true)}<span class="track-play-overlay">${icon(active&&ui.playing?"pause":"play")}</span></button><div class="track-details"><button class="track-title" style="background:none;border:0;padding:0;text-align:left;max-width:100%" data-action="play" data-id="${t.id}">${esc(t.title)}</button><small><button style="border:0;background:none;color:inherit;padding:0" data-route="artist/${a.id}">${esc(a.name)}</button> · ${esc(a.genre.split("/")[0].trim())}</small></div>${wave(t.id)}<div class="track-right"><span class="track-duration">${fmtTime(t.duration)}</span><button class="row-action ${liked?"on":""}" data-action="like" data-id="${t.id}" aria-label="${liked?"좋아요 취소":"좋아요"}" title="좋아요">${icon("heart")}</button><button class="row-action ${saved?"on":""}" data-action="save" data-id="${t.id}" aria-label="플레이리스트 저장" title="플레이리스트에 저장">${icon(saved?"check":"bookmark")}</button><button class="row-action" data-action="share" data-type="track" data-id="${t.id}" title="공유" aria-label="공유">${icon("share")}</button></div></div>`}
function trackList(list){return `<div class="track-list">${list.map((t,i)=>trackRow(t,i)).join("")}</div>`}
function statBox(){return `<div class="stats-row"><div class="stat"><span class="stat-icon">${icon("radio")}</span><div><b>06</b><small>HIDDEN ARTISTS</small></div></div><div class="stat"><span class="stat-icon">${icon("headphones")}</span><div><b>12</b><small>ORIGINAL DEMO TRACKS</small></div></div><div class="stat"><span class="stat-icon">${icon("badge")}</span><div><b>03</b><small>WAYS TO PARTICIPATE</small></div></div></div>`}
function renderDiscover(){return `
  <section class="hero"><div class="hero-content"><div class="hero-stamp"><i class="live-dot"></i> HIDDEN STAGE / VOL. 01</div><h1>GOOD MUSIC.<br><em>NEW VOICES.</em></h1><p>아직 세상에 알려지지 않은 음악을 먼저 발견하고, 듣고, 응원하세요. 당신의 작은 발견이 누군가의 다음 무대를 만듭니다.</p><div class="hero-buttons">${link(icon("play")+" Hidden Stage 입장","hidden-stage")}${link("어떻게 참여하나요? "+icon("arrow-right"),"missions","secondary")}</div></div><div class="hero-side"><span class="mini-badge">${icon("radio")} SIGNAL IS LIVE</span><span class="hero-code">DISCOVER / LISTEN / SUPPORT</span><span class="hero-counter">SC—001 / 2026</span></div></section>
  <div class="marquee"><strong>NOW ON AIR</strong><span class="mono">누군가의 첫 번째 리스너가 되어보세요. · HIDDEN STAGE / NEW DISCOVERIES EVERY DAY</span><span class="arrow">${icon("arrow-right")}</span></div>
  ${statBox()}
  <section class="section">${sectionHead("Fresh signals","지금 주목해야 할 아티스트","hidden-stage","아티스트 더 보기")}<div class="artist-grid">${artists.slice(0,3).map(artistCard).join("")}</div></section>
  <section class="section"><div class="pulse-card"><div><span class="eyebrow">DISCOVER DROP / PERSONAL PICK</span><h3>지금, 새로운 음악에<br>우연히 빠질 시간.</h3><p>늘 듣던 음악에서 벗어나 당신의 취향과 맞닿은 다음 아티스트를 만나보세요.</p>${link(icon("sparkles")+" Mood Finder 시작하기","for-you")}<div class="pill-stats"><span>01 / CHOOSE A MOOD</span><span>02 / FIND A VOICE</span></div></div><div class="pulse-cover">${cover(artists[2])}</div></div></section>
  <section class="section">${sectionHead("Play something undiscovered","숨겨진 아티스트의 새 트랙을 먼저 들어보세요","charts","차트 보기")}${trackList([tracks[0],tracks[2],tracks[4],tracks[6],tracks[8]])}</section>
  <section class="section"><div class="page-banner mission"><span class="eyebrow">FIRST LISTENER / PARTICIPATE</span><h2 style="font-size:clamp(29px,3.5vw,40px);margin:18px 0 12px">듣는 것에서 끝나지 않는<br>음악 경험.</h2><p>새로운 음악을 듣고, 아티스트를 팔로우하고, 발견을 공유하면 당신만의 First Listener 배지를 기록할 수 있어요.</p><div class="banner-actions">${link("참여 미션 시작하기 "+icon("arrow-right"),"missions")}${link("응원 현황 보기","community","secondary")}</div></div></section>
  <section class="section">${sectionHead("Next up","더 많은 새로운 목소리","hidden-stage","더 발견하기")}<div class="artist-grid">${artists.slice(3,6).map((a,i)=>artistCard(a,i+3)).join("")}</div></section>`}
function renderHiddenStage(){return `<section class="page-banner"><span class="banner-mark">PROMOTION / VOLUME 001</span><span class="eyebrow"><i class="live-dot"></i> HIDDEN STAGE · SOUND CLOUD REDESIGN</span><h1>THE STAGE IS<br>YOURS TO FIND.</h1><p>인기 차트 밖에 있는 좋은 음악을 더 쉽게 만나고, 발견을 더 많은 사람과 공유하는 새로운 사운드클라우드 경험.</p><div class="banner-actions">${link(icon("headphones")+" 오늘의 첫 청취 시작","missions")}${link(icon("trophy")+" 커뮤니티 응원 현황","community","secondary")}</div></section>
<section class="section">${sectionHead("The hidden lineup","세 가지 색의 사운드, 세 번의 발견")}<div class="stage-grid">${artists.slice(0,3).map((a,i)=>`<article class="stage-card"><span class="stage-no">DAY 0${i+1} / HIDDEN STAGE</span>${cover(a)}<h3>${esc(a.name)}</h3><p>${esc(a.subtitle)}</p>${link("아티스트 만나기 "+icon("arrow-right"),"artist/"+a.id,"small")}</article>`).join("")}</div></section>
<section class="section">${sectionHead("How a discovery becomes support","듣기 → 팔로우 → 공유, 세 단계 참여")}
<div class="mission-steps">
<div class="mission-step"><span class="step-n">01</span><div><h3>DISCOVER / 새로운 음악 듣기</h3><p>처음 듣는 음악의 8초 미리듣기를 완료합니다.</p></div>${icon("headphones")}</div>
<div class="mission-step"><span class="step-n">02</span><div><h3>SUPPORT / 아티스트 팔로우</h3><p>다음 곡도 기대되는 아티스트에게 관심을 표시해 보세요.</p></div>${icon("heart")}</div>
<div class="mission-step"><span class="step-n">03</span><div><h3>SHARE / 발견 널리 알리기</h3><p>나만 알고 있던 음악을 다른 리스너에게 소개합니다.</p></div>${icon("share")}</div>
</div><div style="margin-top:15px">${link("First Listener 미션 참여하기","missions")}</div></section>
<section class="section">${sectionHead("Hidden music on repeat","세상에 소개하고 싶은 음악")}${trackList([tracks[0],tracks[2],tracks[4]])}</section>`}
function renderCharts(){const options=["all","Electronic","Indie","Lo-fi","Pop","Ambient"];const filtered=ui.genre==="all"?tracks:tracks.filter(t=>artist(t.artist).genre.toLowerCase().includes(ui.genre.toLowerCase())||ui.genre==="Ambient"&&t.sound==="air");const sorted=[...filtered].sort((a,b)=>(b.plays+(listHas("liked",b.id)?1:0))-(a.plays+(listHas("liked",a.id)?1:0)));return `<section>${pageHead("DISCOVERY CHARTS","Not the usual top 50.","익숙한 순위보다 새로운 가능성. 장르별로 숨어 있던 음악을 찾아보세요.")}<div class="chips" style="margin:19px 0 26px">${options.map(x=>`<button data-action="genre" data-id="${x}" class="chip ${ui.genre===x?"active":""}">${x==="all"?"All sounds":esc(x)}</button>`).join("")}</div>${sorted.length?trackList(sorted):`<div class="empty-state">${icon("music")}<h3>아직 등록된 트랙이 없어요</h3><p>다른 장르를 선택해보세요.</p></div>`}</section>`}
function renderForYou(){const moods=[{id:"night",title:"Midnight drive",sub:"도시의 야경 · 전자음악",icon:"🌙",a:"#e96637"},{id:"calm",title:"Slow down",sub:"차분한 하루 · 인디",icon:"☁️",a:"#9d7a9b"},{id:"focus",title:"Deep focus",sub:"흐름을 놓치지 않는 비트",icon:"◉",a:"#846ac8"},{id:"energy",title:"Fresh energy",sub:"기분을 바꾸는 새 목소리",icon:"✳",a:"#70a6a3"}];const pick=artists.filter(a=>a.mood===ui.mood);const drop=pick[ui.dropIndex%Math.max(1,pick.length)]||artists[0];return `<section>${pageHead("MOOD FINDER / FOR YOU","What are you feeling?","당신의 오늘에 맞는 기분 하나만 골라보세요. 새로운 아티스트를 만날 수 있는 발견 경로가 열립니다.")}<div class="mood-choices">${moods.map(m=>`<button data-action="mood" data-id="${m.id}" class="mood-card ${ui.mood===m.id?"selected":""}" style="--a:${m.a}"><span class="mood-icon">${m.icon}</span><strong>${m.title}</strong><small>${m.sub}</small></button>`).join("")}</div>
<section class="section">${sectionHead("Your Discover Drop","취향에서 시작되는 오늘의 발견")}<div class="drop-reveal">${cover(drop)}<div><span class="eyebrow">PICKED FOR YOUR MOOD</span><h3>${esc(drop.name)}</h3><p>${esc(drop.subtitle)}<br>${esc(drop.genre)} · ${esc(drop.city)}</p><div style="display:flex;gap:8px;flex-wrap:wrap">${btn(icon("play")+" 미리듣기","play","small")}<button class="btn small secondary" data-route="artist/${drop.id}">프로필 보기 ${icon("arrow-right")}</button><button class="btn small ghost" data-action="next-drop">${icon("shuffle")} 다시 뽑기</button></div><input id="drop-track" type="hidden" value="${drop.tracks[0]}"></div></div></section>
<section class="section">${sectionHead("More like this","선택한 기분과 어울리는 음악")}${trackList(pick.flatMap(a=>a.tracks.map(track)))}</section></section>`}
function renderMissions(){const steps=earnedSteps(),pct=missionPct();return `<section>${pageHead("FIRST LISTENER / PARTICIPATE","Hear it first.<br>Help it grow.","음악을 듣고, 아티스트를 팔로우하고, 발견을 공유하세요. 참여의 기록이 특별한 배지로 남습니다.")}<div class="mission-progress"><span class="eyebrow" style="font-size:10px">MISSION PROGRESS</span><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><b class="mono" style="color:#ff9a6b">${pct.toFixed(0)}%</b></div><div class="mission-layout"><div class="mission-steps">
${[{title:"LISTEN FIRST",sub:"아래 음악을 8초 이상 들어보세요.",done:steps[0],ico:"headphones",action:"play",id:"signal-live",label:"음악 듣기"},{title:"FOLLOW AN ARTIST",sub:"처음 발견한 아티스트를 한 명 이상 팔로우하세요.",done:steps[1],ico:"user-plus",route:"hidden-stage",label:"아티스트 찾기"},{title:"SHARE THE DISCOVERY",sub:"좋은 음악을 다른 리스너에게 소개하세요.",done:steps[2],ico:"share",action:"share",id:"signal-live",label:"음악 공유"}].map((z,i)=>`<div class="mission-step ${z.done?"done":""}"><span class="step-n">0${i+1}</span><div><h3>${z.title}</h3><p>${z.sub}</p><button class="link-btn" style="padding:7px 0 0" ${z.route?`data-route="${z.route}"`:`data-action="${z.action}" data-id="${z.id}" data-type="track"`}>${z.done?"완료":z.label} ${icon(z.done?"check":"arrow-right")}</button></div>${icon(z.done?"check":"clock")}</div>`).join("")}</div>
<div class="badge-panel"><div class="badge-seal ${state.badge?"":"locked"}"><strong>FIRST</strong><strong>LISTENER</strong><span>HS / VOL.01</span></div><h3>${state.badge?"You earned it.":"The first to know."}</h3><p>${state.badge?"당신의 라이브러리에 배지가 저장됐어요.":"세 가지 미션을 완료하면 배지가 활성화됩니다."}</p>${state.badge?link("내 배지 보기","library","small"):steps.every(Boolean)?btn("배지 획득하기","claim-badge","small"):btn("미션 진행 중","claim-badge","small secondary")}</div></div>
<section class="section">${sectionHead("Start with these tracks","당신의 첫 발견을 기다리는 음악")}${trackList([tracks[0],tracks[2],tracks[4]])}</section></section>`}
function renderCommunity(){const rank=[...artists].sort((a,b)=>(b.base+(listHas("following",b.id)?1:0))-(a.base+(listHas("following",a.id)?1:0)));return `<section>${pageHead("COMMUNITY / SHARE TO SUPPORT","Give the unheard<br>a bigger stage.","사용자의 청취와 참여가 아티스트의 발견 가능성을 높인다는 아이디어를 시각화한 응원 공간입니다. 아래 수치는 시연용 데이터입니다.")}<div class="rank-table">${rank.map((a,i)=>`<div class="rank-row"><span class="rank-num">${String(i+1).padStart(2,"0")}</span><button data-route="artist/${a.id}" style="padding:0;border:0;background:none">${cover(a,true)}</button><div><h3><button data-route="artist/${a.id}" style="border:0;background:none;color:inherit;font-weight:800;padding:0">${esc(a.name)}</button></h3><p>${esc(a.genre)}</p></div><div class="metrics"><b>${fmtNum(a.base+(listHas("following",a.id)?1:0))}</b><small>DEMO SUPPORT</small></div></div>`).join("")}</div>
<section class="section"><div class="page-banner mission" style="min-height:190px"><span class="eyebrow">LISTEN / LIKE / FOLLOW / SHARE</span><h2 style="margin:16px 0;font-size:28px">그냥 지나치지 않고,<br>다음 무대를 함께 만든다.</h2><div class="banner-actions">${link("새로운 음악 발견하기","hidden-stage","small")}${link("참여 미션 확인","missions","small secondary")}</div></div></section></section>`}
function renderLibrary(){const savedTracks=tracks.filter(t=>listHas("saved",t.id)||listHas("liked",t.id)),followed=artists.filter(a=>listHas("following",a.id));return `<section>${pageHead("YOUR DISCOVERIES","Your sound.<br>Your people.","좋아한 음악과 저장한 트랙, 직접 발견한 아티스트를 한곳에서 확인하세요. 기록은 현재 브라우저에 저장됩니다.")}<div class="library-overview"><div class="library-stat">${icon("heart")}<strong>${state.liked.length}</strong><small>LIKED TRACKS</small></div><div class="library-stat">${icon("user-plus")}<strong>${state.following.length}</strong><small>FOLLOWED ARTISTS</small></div><div class="library-stat">${icon("badge")}<strong>${state.badge?"01":"00"}</strong><small>FIRST LISTENER BADGE</small></div></div>
<section class="section">${sectionHead("Your First Listener Badge","처음 발견한 음악의 기록")}<div class="pulse-card"><div><span class="eyebrow">HIDDEN STAGE / PERSONAL ACHIEVEMENT</span><h3>${state.badge?"FIRST LISTENER / UNLOCKED":"FIRST LISTENER / LOCKED"}</h3><p>좋은 음악을 먼저 발견하고 아티스트의 새로운 팬이 되어보세요. 직접 참여한 흔적을 남길 수 있습니다.</p>${link(state.badge?"내 미션 기록 보기":"첫 리스너 미션 시작","missions","small")}</div><div class="badge-panel" style="min-height:190px"><div class="badge-seal ${state.badge?"":"locked"}"><strong>FIRST</strong><strong>LISTENER</strong><span>HS / VOL.01</span></div></div></div></section>
<section class="section">${sectionHead("Saved tracks","좋아요와 저장한 음악","discover","더 발견하기")}${savedTracks.length?trackList(savedTracks):`<div class="empty-state">${icon("bookmark")}<h3>아직 저장한 음악이 없어요.</h3><p>좋아하는 트랙의 하트 또는 저장 버튼을 눌러보세요.</p>${link("새 음악 찾아보기","discover","small")}</div>`}</section>
<section class="section">${sectionHead("Followed artists","당신이 응원하는 아티스트","hidden-stage","아티스트 발견하기")}${followed.length?`<div class="artist-grid">${followed.map((a,i)=>artistCard(a,i)).join("")}</div>`:`<div class="empty-state">${icon("users")}<h3>아직 팔로우한 아티스트가 없어요.</h3><p>새롭게 발견한 아티스트의 첫 번째 팬이 되어보세요.</p></div>`}</section></section>`}
function renderArtist(a){return `<section><div class="artist-hero" ${cssvars(a)}>${cover(a)}<div class="artist-hero-copy"><span class="eyebrow">HIDDEN STAGE / ARTIST ${esc(a.code)}</span><h1>${esc(a.name)}</h1><p>${esc(a.genre)} · ${esc(a.city)}</p><div class="artist-actions"><button class="btn" data-action="play" data-id="${a.tracks[0]}">${icon("play")} Play latest</button><button class="btn secondary" data-action="follow" data-id="${a.id}">${icon(listHas("following",a.id)?"check":"plus")} ${listHas("following",a.id)?"Following":"Follow artist"}</button><button class="btn ghost" data-action="share" data-type="artist" data-id="${a.id}" aria-label="아티스트 공유">${icon("share")}</button></div></div></div>
<div class="artist-story"><div><span class="eyebrow">ABOUT THE ARTIST</span><h3 style="margin-top:13px">${esc(a.subtitle)}</h3><p>${esc(a.story)}</p></div><div class="stat-board"><div><b>${esc(a.code)}</b><span>STAGE ARTIST NO.</span></div><div><b>${fmtNum(a.base)}</b><span>DEMO SUPPORT COUNT</span></div></div></div>
<section class="section">${sectionHead("Tracks by "+esc(a.name),"새로운 음악을 만나보세요")}${trackList(a.tracks.map(track))}</section>
<section class="section">${sectionHead("Bring this sound to someone else","나만 알고 있던 좋은 음악을 공유하세요")}<div class="pulse-card"><div><span class="eyebrow">SHARE TO SUPPORT</span><h3>Every first fan<br>makes a difference.</h3><p>누군가의 처음이 될 수 있도록, 마음에 든 아티스트의 음악을 공유해보세요.</p><button class="btn" data-action="share" data-type="artist" data-id="${a.id}">${icon("share")} 이 아티스트 공유하기</button></div><div class="pulse-cover">${cover(a)}</div></div></section>
<section class="section">${sectionHead("More voices to discover","다른 숨겨진 아티스트도 만나보세요","hidden-stage","전체 보기")}<div class="artist-grid">${artists.filter(x=>x.id!==a.id).slice(0,3).map((v,i)=>artistCard(v,i)).join("")}</div></section></section>`}
function renderSearch(){const query=new URLSearchParams(routeNow().split("?")[1]||"").get("q")||"";const q=query.trim().toLowerCase();const as=artists.filter(a=>(a.name+" "+a.genre+" "+a.city).toLowerCase().includes(q));const ts=tracks.filter(t=>(t.title+" "+artist(t.artist).name+" "+artist(t.artist).genre).toLowerCase().includes(q));return `<section>${pageHead("SEARCH / MUSIC & ARTISTS",q?'Results for "'+esc(query)+'"':"Search the hidden stage.","장르와 아티스트, 트랙 이름으로 새로운 음악을 찾을 수 있습니다.")}<section class="section">${sectionHead("Artists",as.length+" results")}${as.length?`<div class="artist-grid">${as.map((a,i)=>artistCard(a,i)).join("")}</div>`:`<div class="empty-state">${icon("search")}<h3>일치하는 아티스트가 없어요.</h3><p>다른 검색어를 사용해보세요.</p></div>`}</section><section class="section">${sectionHead("Tracks",ts.length+" results")}${ts.length?trackList(ts):`<div class="empty-state"><p>검색된 트랙이 없습니다.</p></div>`}</section></section>`}
function renderSubmit(){return `<section>${pageHead("OPEN CALL / ARTIST SUBMISSION","Put a new voice<br>on the radar.","아직 알려지지 않은 아티스트를 소개하는 참여 화면입니다. 제출 내용은 서버로 전송되지 않고 현재 브라우저에만 저장됩니다.")}<div class="pulse-card" style="display:block;max-width:650px"><span class="eyebrow">RECOMMEND AN ARTIST</span><h2 style="margin:16px 0 23px">누군가에게 알려주고 싶은<br>그 음악을 추천해 주세요.</h2><form id="submission-form"><div class="form-grid"><div class="form-group"><label for="artist-name">아티스트명 *</label><input class="field" maxlength="60" required id="artist-name" name="name" placeholder="아티스트 이름"></div><div class="form-group"><label for="artist-genre">장르 *</label><select class="field" required id="artist-genre" name="genre"><option value="">장르 선택</option><option>Electronic</option><option>Indie</option><option>Lo-fi</option><option>Pop</option><option>Alternative</option><option>Other</option></select></div></div><div class="form-group"><label for="artist-link">음악 링크 (선택)</label><input class="field" type="url" maxlength="250" id="artist-link" name="url" placeholder="https://soundcloud.com/..."></div><div class="form-group"><label for="artist-reason">추천 이유 *</label><textarea class="field" maxlength="400" required id="artist-reason" name="reason" placeholder="왜 이 아티스트의 음악을 다른 사람에게 소개하고 싶나요?"></textarea></div><button type="submit" class="btn">${icon("send")} 추천 등록 (로컬 데모)</button><p class="form-hint" style="margin:12px 0 0">개인정보를 입력하지 마세요. 서버 수신 기능이 없는 포트폴리오 시연용 폼입니다.</p></form></div><section class="section">${sectionHead("My recommendations","이 브라우저에서 등록한 추천")}${state.submitted.length?state.submitted.map(x=>`<div class="rail-feed-item" style="border:1px solid var(--line);border-radius:11px;padding:14px;margin:9px 0">${icon("radio")}<div><strong>${esc(x.name)}</strong> · ${esc(x.genre)}<p style="margin:5px 0">${esc(x.reason)}</p></div></div>`).join(""):`<div class="empty-state"><p>아직 등록한 추천이 없습니다.</p></div>`}</section></section>`}
function mainMarkup(){const route=currentView();if(route==="discover")return renderDiscover();if(route==="hidden-stage")return renderHiddenStage();if(route==="charts")return renderCharts();if(route==="for-you")return renderForYou();if(route==="missions")return renderMissions();if(route==="community")return renderCommunity();if(route==="library")return renderLibrary();if(route==="submit")return renderSubmit();if(route==="search")return renderSearch();if(route.startsWith("artist/"))return renderArtist(artist(route.split("/")[1]));return `<div class="empty-state">${icon("compass")}<h3>페이지를 찾을 수 없어요</h3>${link("Discover로 돌아가기","discover")}</div>`}
const navItems=[["discover","compass","Discover"],["hidden-stage","radio","Hidden Stage"],["charts","chart","Charts"],["for-you","sparkles","For you"],["community","users","Community"],["library","library","My Library"]];
function navActive(route,id){return route===id||id==="hidden-stage"&&route.startsWith("artist/")||id==="discover"&&route==="search"}
function renderSidebar(){const route=currentView();$("#sidebar").innerHTML=`<div class="logo-wrap"><div class="logo-mark">${icon("radio")}</div><div><div class="brand-main">soundcloud<span style="color:var(--orange)">.</span></div><div class="brand-sub">HIDDEN STAGE / REIMAGINED</div></div></div><div class="nav-label">BROWSE / 01</div><div class="side-nav">${navItems.map(n=>`<button class="side-link ${navActive(route,n[0])?"active":""}" data-route="${n[0]}">${icon(n[1])}<span>${n[2]}</span>${n[0]==="library"&&state.liked.length?`<span class="side-counter">${state.liked.length}</span>`:""}</button>`).join("")}</div><div class="sidebar-divider"></div><div class="nav-label">HIDDEN ARTISTS / LIVE</div><div class="side-nav">${artists.slice(0,4).map(a=>`<button class="side-artist" data-route="artist/${a.id}">${avatar(a)}<span><strong>${esc(a.name)}</strong><small>${esc(a.genre.split("/")[0].trim())}</small></span></button>`).join("")}</div><div class="sidebar-bottom"><div class="sidebar-promo"><span class="eyebrow">FIRST LISTENER</span><b>Your ears.<br>Their next stage.</b><button data-route="missions">참여 미션 시작하기 ${icon("arrow-right")}</button></div><div class="side-foot"><i class="live-dot"></i> DISCOVER FIRST / SUPPORT MORE</div></div>`}
function renderTopbar(){const inputValue=esc(ui.searchValue);$("#topbar").innerHTML=`<div class="topbar-mobile-brand"><div class="logo-mark">${icon("radio")}</div><span>soundcloud<span style="color:var(--orange)">.</span></span></div><div class="topbar-search">${icon("search")}<input id="global-search" type="search" aria-label="아티스트와 음악 검색" autocomplete="off" placeholder="Search artists, tracks, moods..." value="${inputValue}"><span class="search-shortcut">/</span></div><div class="topbar-right"><span class="topbar-label"><i class="live-dot"></i> HIDDEN STAGE / VOL.01</span><button class="pill-cta btn secondary small" data-route="submit">${icon("upload")} 아티스트 추천</button><button class="icon-btn hide-mobile" title="알림" data-action="modal" data-id="notifications">${icon("bell")}</button><button class="icon-btn" title="계정" data-action="modal" data-id="account"><span class="top-avatar">HS</span></button></div><div id="search-menu" class="search-menu"></div>`;if(ui.searchOpen&&ui.searchValue)renderSuggestions()}
function renderSuggestions(){const menu=$("#search-menu");if(!menu)return;const q=ui.searchValue.trim().toLowerCase();if(!q){menu.classList.remove("show");return}const as=artists.filter(a=>a.name.toLowerCase().includes(q)||a.genre.toLowerCase().includes(q)).slice(0,3);const ts=tracks.filter(t=>t.title.toLowerCase().includes(q)||artist(t.artist).name.toLowerCase().includes(q)).slice(0,4);menu.classList.add("show");menu.innerHTML=`<div class="search-help">SEARCH / ${esc(ui.searchValue)} · ENTER TO VIEW ALL</div>${as.map(a=>`<button class="search-item" data-route="artist/${a.id}">${avatar(a)}<span>${esc(a.name)}<small>Artist / ${esc(a.genre)}</small></span></button>`).join("")}${ts.map(t=>`<button class="search-item" data-action="play" data-id="${t.id}">${cover(artist(t.artist),true)}<span>${esc(t.title)}<small>${esc(artist(t.artist).name)} / Track</small></span></button>`).join("")}${!as.length&&!ts.length?'<div class="search-help">일치하는 결과가 없습니다.</div>':''}<button class="search-item" data-route="search?q=${encodeURIComponent(ui.searchValue)}">${icon("arrow-right")} <span>모든 검색 결과 보기</span></button>`}
function renderRail(){const trending=[...artists].sort((a,b)=>b.base-a.base).slice(0,4);$("#rail").innerHTML=`<div class="rail-section"><div class="rail-title">FEATURED EVENT <span>VOL.01</span></div><div class="rail-feature"><span class="eyebrow"><i class="live-dot"></i> LIVE PROMOTION</span><h3>Hidden<br>Stage.</h3><p>누구보다 먼저 발견하고, 더 많은 사람에게 소개하는 참여형 음악 경험.</p>${link("STAGE ENTER "+icon("arrow-right"),"hidden-stage","small")}</div></div><div class="rail-section"><div class="rail-title">ARTISTS ON THE RISE <span>${icon("arrow-up-right")}</span></div>${trending.map((a,i)=>`<button class="rail-user" data-route="artist/${a.id}">${avatar(a)}<span><strong>${esc(a.name)}</strong><small>${esc(a.genre)}</small></span><span class="rank-num">0${i+1}</span></button>`).join("")}</div><div class="rail-section"><div class="rail-title">YOUR PROGRESS <span>${earnedSteps().filter(Boolean).length}/3</span></div><div class="progress-track"><div class="progress-fill" style="width:${missionPct()}%"></div></div><p style="font-size:11px;margin:12px 0 9px">당신의 첫 청취가 특별한 배지로 남는 순간.</p><button class="link-btn" data-route="missions">미션 확인하기 ${icon("arrow-right")}</button></div><div class="rail-section"><div class="rail-title">COMMUNITY PULSE <span>LIVE</span></div><div class="rail-feed-item"><div class="feed-icon">${icon("headphones")}</div><div><strong>First Listener</strong> 미리듣기 체험 시작<time>DISCOVER / TODAY</time></div></div><div class="rail-feed-item"><div class="feed-icon">${icon("heart")}</div><div>당신의 좋아요가 다음 음악 발견으로 이어집니다.<time>SUPPORT / EVERY DAY</time></div></div><div class="rail-feed-item"><div class="feed-icon">${icon("share")}</div><div>나만 알고 있던 아티스트를 소개해보세요.<time>SHARE / NEXT STAGE</time></div></div></div><div class="rail-section"><div class="rail-title">ABOUT THIS PROJECT</div><p style="font-size:10px;line-height:1.8;color:#89838d">SoundCloud UI/UX 콘셉트 리디자인 · 김준서<br>아티스트명·청취 수치와 오디오는 시연용입니다.</p></div>`}
function renderMobileNav(){const route=currentView();const nav=[["discover","compass","홈"],["hidden-stage","radio","발견"],["charts","chart","차트"],["for-you","sparkles","취향"],["library","library","보관함"]];$("#mobile-nav").innerHTML=nav.map(n=>`<button class="${navActive(route,n[0])?"active":""}" data-route="${n[0]}">${icon(n[1])}<span>${n[2]}</span></button>`).join("")}
function renderPlayer(){const t=track(state.trackId),a=artist(t.artist),progress=Math.min(100,ui.currentTime/t.duration*100);$("#player").innerHTML=`<div class="player-track">${cover(a,true)}<div class="player-info"><strong>${esc(t.title)}</strong><small>${esc(a.name)} · Original demo preview</small></div></div><div class="player-controls"><div class="player-buttons"><button class="player-control ${state.shuffle?"on":""}" data-action="shuffle" title="셔플">${icon("shuffle")}</button><button class="player-control" data-action="prev" title="이전">${icon("skip-back")}</button><button class="player-control primary" data-action="toggle-play" title="${ui.playing?"일시정지":"재생"}">${icon(ui.playing?"pause":"play")}</button><button class="player-control" data-action="next" title="다음">${icon("skip-next")}</button><button class="player-control ${state.repeat?"on":""}" data-action="repeat" title="반복">${icon("repeat")}</button></div><div class="progress-row"><span class="time" id="time-current">${fmtTime(ui.currentTime)}</span><input class="seek" id="player-seek" type="range" min="0" max="${t.duration}" step=".1" value="${ui.currentTime}" style="--progress:${progress}%" aria-label="재생 위치"><span class="time">${fmtTime(t.duration)}</span></div></div><div class="player-extra"><button class="icon-btn ${listHas("liked",t.id)?"active":""}" data-action="like" data-id="${t.id}" title="좋아요">${icon("heart")}</button><button class="icon-btn" data-action="modal" data-id="queue" title="재생목록">${icon("list")}</button><button class="icon-btn" data-action="volume-toggle" title="음소거">${icon(state.volume?"volume":"mute")}</button><div class="volume"><input type="range" class="seek" id="volume-range" min="0" max="100" value="${state.volume}" style="--progress:${state.volume}%" aria-label="볼륨"></div></div><div class="player-mobile-play"><button data-action="toggle-play" aria-label="${ui.playing?"일시정지":"재생"}">${icon(ui.playing?"pause":"play")}</button><button data-action="next" aria-label="다음 곡">${icon("skip-next")}</button></div>`}
function render(clearScroll=false){renderSidebar();renderTopbar();$("#main").innerHTML=mainMarkup();renderRail();renderMobileNav();renderPlayer();if(clearScroll){$("#workspace").scrollTop=0;ui.searchOpen=false;}updatePlayerProgress()}
function renderKeep(){const w=$("#workspace");const y=w.scrollTop;render(false);w.scrollTop=y}
function updatePlayerProgress(){const t=track(state.trackId),pct=Math.min(100,ui.currentTime/t.duration*100),range=$("#player-seek"),clock=$("#time-current"),p=$("#player");if(range){range.value=ui.currentTime;range.style.setProperty("--progress",pct+"%")}if(clock)clock.textContent=fmtTime(ui.currentTime);if(p)p.style.setProperty("--progress",pct+"%")}

let ctx=null,gain=null,loopTimer=null,step=0,nextStep=0,startPerf=0,noiseBuffer=null,clockRun=0,trackStart=0,lastListenWhole=0;
function initAudio(){if(ctx)return true;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error("unsupported");ctx=new AC();gain=ctx.createGain();gain.gain.value=state.volume/100*.40;gain.connect(ctx.destination);noiseBuffer=ctx.createBuffer(1,Math.floor(ctx.sampleRate*.08),ctx.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.exp(-7*i/data.length);return true}catch(err){toast("이 브라우저에서는 오디오 미리듣기를 지원하지 않습니다.");return false}}
function midi(note){return 440*Math.pow(2,(note-69)/12)}
function note(freq,at,dur,type="sine",loud=.07){if(!ctx||!gain)return;const o=ctx.createOscillator(),g=ctx.createGain(),f=ctx.createBiquadFilter();f.type="lowpass";f.frequency.value=type==="sawtooth"?1900:2400;o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(Math.max(.0002,loud),at+.018);g.gain.exponentialRampToValueAtTime(.0001,at+dur);o.connect(f);f.connect(g);g.connect(gain);o.start(at);o.stop(at+dur+.03)}
function kick(at){const o=ctx.createOscillator(),g=ctx.createGain();o.type="sine";o.frequency.setValueAtTime(127,at);o.frequency.exponentialRampToValueAtTime(42,at+.13);g.gain.setValueAtTime(.14,at);g.gain.exponentialRampToValueAtTime(.0001,at+.20);o.connect(g);g.connect(gain);o.start(at);o.stop(at+.22)}
function hat(at){if(!noiseBuffer)return;const o=ctx.createBufferSource(),g=ctx.createGain(),bp=ctx.createBiquadFilter();o.buffer=noiseBuffer;bp.type="highpass";bp.frequency.value=4800;g.gain.value=.095;o.connect(bp);bp.connect(g);g.connect(gain);o.start(at)}
function scheduleStep(t,s,at){const base=t.root,scale=[0,2,3,5,7,10,12,14],offset=[0,0,5,3][Math.floor(s/16)%4],stepIn=s%16;const toneKind=t.sound==="lofi"?"sine":t.sound==="analog"?"sawtooth":t.sound==="bright"?"triangle":"sine";const beat=60/t.bpm;if(stepIn%4===0)kick(at);if(stepIn%2===0)hat(at);if(stepIn%8===0){note(midi(base-12+offset),at,beat*.95,"sine",.16);[0,3,7].forEach((v,j)=>note(midi(base+offset+v),at,beat*2.1,toneKind,.024-j*.003))}const melody=[0,2,4,2,5,4,2,1,0,3,5,4,2,1,0,4];if(stepIn%2===0){let n=melody[stepIn],freq=midi(base+12+offset+scale[n%scale.length]);note(freq,at,beat*.39,toneKind,t.sound==="air"?.025:.044)}}
function sched(){if(!ui.playing||!ctx)return;const t=track(state.trackId),interval=60/t.bpm/2;while(nextStep<ctx.currentTime+.12){scheduleStep(t,step,nextStep);nextStep+=interval;step++}}
function stopAudio(){if(loopTimer){clearInterval(loopTimer);loopTimer=null}}
function setPlaying(v){if(!v){ui.playing=false;stopAudio();renderPlayer();return}if(!initAudio())return;ctx.resume().catch(()=>{});ui.playing=true;step=0;nextStep=ctx.currentTime+.06;stopAudio();loopTimer=setInterval(sched,85);startPerf=performance.now()-ui.currentTime*1000;lastListenWhole=Math.floor(ui.currentTime);sched();renderPlayer()}
function playTrack(id){const t=track(id);if(state.trackId===t.id&&ui.playing){setPlaying(false);toast("일시정지");return}if(state.trackId!==t.id){state.trackId=t.id;ui.currentTime=0;state.recent=[t.id,...state.recent.filter(x=>x!==t.id)].slice(0,10);persist()}setPlaying(true);renderKeep();toast(t.title+" · 재생 시작")}
function nextTrack(direction=1){const index=tracks.findIndex(x=>x.id===state.trackId);const next=state.shuffle?tracks[Math.floor(Math.random()*tracks.length)]:tracks[(index+direction+tracks.length)%tracks.length];state.trackId=next.id;ui.currentTime=0;state.recent=[next.id,...state.recent.filter(x=>x!==next.id)].slice(0,10);persist();if(ui.playing)setPlaying(true);else renderPlayer();renderKeep()}
function seekTo(v){ui.currentTime=Math.min(track(state.trackId).duration,Math.max(0,Number(v)||0));if(ui.playing)setPlaying(true);updatePlayerProgress()}
function tick(ts){if(ui.playing){ui.currentTime=Math.min(track(state.trackId).duration,(ts-startPerf)/1000);const whole=Math.floor(ui.currentTime);if(whole>lastListenWhole){const elapsed=Math.max(1,whole-lastListenWhole);lastListenWhole=whole;state.heard[state.trackId]=(state.heard[state.trackId]||0)+elapsed;if(state.heard[state.trackId]>=8&&ui.lastCount!==1){ui.lastCount=1;persist();toast("듣기 미션 완료! 다른 단계도 진행해보세요.");claimBadge();if(currentView()==="missions")renderKeep()}}if(ui.currentTime>=track(state.trackId).duration){if(state.repeat){ui.currentTime=0;setPlaying(true)}else nextTrack(1)}updatePlayerProgress()}requestAnimationFrame(tick)}
function modal(type,id){ui.modal=type;ui.modalData=id;renderModal()}
function closeModal(){ui.modal=null;ui.modalData=null;const node=$("#modal-root");node.innerHTML=""}
function renderModal(){const root=$("#modal-root");if(!ui.modal){root.innerHTML="";return}const type=ui.modal,kind=ui.modalData||state.trackId;
let title="",body="",wide=false;
if(type==="share"){const isArtist=kind.startsWith("artist:");const v=isArtist?artist(kind.slice(7)):track(kind);const a=isArtist?v:artist(v.artist);const url=location.origin+location.pathname+"#/artist/"+a.id;title="Share the discovery";body=`<p class="modal-desc">숨겨진 음악을 다른 리스너에게 소개하세요. 공유하기를 완료하면 참여 미션에도 반영됩니다.</p><div class="modal-art">${cover(a)}<div><b>${esc(isArtist?a.name:v.title)}</b><small>${esc(a.name)} · Hidden Stage</small></div></div><div class="share-link" id="copy-link">${esc(url)}</div><div class="modal-actions"><button class="btn" data-action="copy-share" data-id="${esc(kind)}">${icon("copy")} 링크 복사하고 공유 완료</button><button class="btn secondary" data-action="native-share" data-id="${esc(kind)}">${icon("share")} 공유 메뉴</button></div>`}
else if(type==="account"){title="Your Hidden Stage";body=`<p class="modal-desc">숨겨진 아티스트를 발견하는 당신의 여정.</p><div class="library-overview"><div class="library-stat">${icon("heart")}<strong>${state.liked.length}</strong><small>LIKES</small></div><div class="library-stat">${icon("users")}<strong>${state.following.length}</strong><small>FOLLOWS</small></div><div class="library-stat">${icon("badge")}<strong>${state.badge?"1":"0"}</strong><small>BADGES</small></div></div><div class="modal-actions">${link("라이브러리 열기","library")}${link("참여 미션 확인","missions","secondary")}</div><p class="form-hint">로그인이나 서버 계정 없이 작동하는 포트폴리오 데모입니다.</p>`}
else if(type==="queue"){title="Up next";wide=true;body=`<p class="modal-desc">선택하면 해당 트랙의 32초 오리지널 데모 사운드를 재생합니다.</p>${trackList(tracks.slice(0,9))}`}
else if(type==="notifications"){title="Community signals";body=`<div class="rail-feed-item"><span class="feed-icon">${icon("radio")}</span><div><strong>Hidden Stage</strong>가 열렸습니다. 새로운 아티스트를 만나보세요.<time>DEMO / TODAY</time></div></div><div class="rail-feed-item"><span class="feed-icon">${icon("badge")}</span><div><strong>First Listener</strong> 미션에 참여해보세요.<time>DEMO / TODAY</time></div></div>${link("미션 보기","missions","small")}`}
else if(type==="badge"){title="First Listener Badge";body=`<div class="badge-panel"><div class="badge-seal ${state.badge?"":"locked"}"><strong>FIRST</strong><strong>LISTENER</strong><span>HS / VOL.01</span></div><h3>${state.badge?"Badge unlocked":"Badge locked"}</h3><p>${state.badge?"미션을 모두 완료했어요.":"듣기·팔로우·공유를 모두 완료하세요."}</p></div><div class="modal-actions">${link("미션 보러 가기","missions")}</div>`}
else if(type==="submit-success"){title="Artist saved locally";body=`<div class="badge-panel">${icon("check")}<h3>추천을 기록했어요</h3><p>현재 브라우저의 데모 데이터에 저장됐습니다. 외부 서버로 전송되지 않습니다.</p></div>${link("추천 목록 확인","submit")}`}
else{title="Hidden Stage";body=`<p class="modal-desc">새로운 음악을 만나보세요.</p>${link("Discover","discover")}`}
root.innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal-panel ${wide?"wide":""}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-top"><span class="eyebrow">SOUNDCLOUD / HIDDEN STAGE</span><button class="icon-btn" data-action="close-modal" aria-label="닫기">${icon("x")}</button></div><h2 class="modal-title">${esc(title)}</h2>${body}</div></div>`;root.querySelector(".modal-panel")?.focus()}
function shareDone(kind){const artistId=kind.startsWith("artist:")?kind.slice(7):track(kind).artist;if(!listHas("shares",artistId)){state.shares.push(artistId);persist();claimBadge()}closeModal();toast("발견을 공유한 참여 기록이 저장됐어요.");renderKeep()}
async function copyShare(kind){let linkTarget=location.origin+location.pathname+"#/artist/"+(kind.startsWith("artist:")?kind.slice(7):track(kind).artist);try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(linkTarget);else{const e=document.createElement("textarea");e.value=linkTarget;e.style.position="fixed";e.style.left="-9999px";document.body.appendChild(e);e.select();document.execCommand("copy");e.remove()}}catch{}shareDone(kind)}
async function nativeShare(kind){const a=artist(kind.startsWith("artist:")?kind.slice(7):track(kind).artist),url=location.origin+location.pathname+"#/artist/"+a.id;if(navigator.share){try{await navigator.share({title:"Hidden Stage — "+a.name,text:"내가 발견한 새로운 음악",url});shareDone(kind)}catch{}}else copyShare(kind)}
function submitForm(form){const fd=new FormData(form);const name=String(fd.get("name")||"").trim(),genre=String(fd.get("genre")||"").trim(),reason=String(fd.get("reason")||"").trim(),url=String(fd.get("url")||"").trim();if(!name||!genre||!reason){toast("필수 입력 항목을 확인해 주세요.");return}state.submitted.unshift({name:name.slice(0,60),genre,reason:reason.slice(0,400),url:url.slice(0,250)});state.submitted=state.submitted.slice(0,20);persist();renderKeep();modal("submit-success")}
function action(el){const type=el.dataset.action,id=el.dataset.id||"",dataType=el.dataset.type||"track";
switch(type){
case"play":{const trackId=id||($("#drop-track")?.value)||state.trackId;playTrack(trackId);break}
case"toggle-play":{setPlaying(!ui.playing);break}
case"next":nextTrack(1);break;
case"prev":nextTrack(-1);break;
case"shuffle":state.shuffle=!state.shuffle;persist();renderPlayer();toast(state.shuffle?"셔플 켜짐":"셔플 꺼짐");break;
case"repeat":state.repeat=!state.repeat;persist();renderPlayer();toast(state.repeat?"반복 재생 켜짐":"반복 재생 꺼짐");break;
case"volume-toggle":{state.volume=state.volume?0:50;if(gain)gain.gain.value=state.volume/100*.4;persist();renderPlayer();break}
case"like":toggleList("liked",id||state.trackId);toast(listHas("liked",id||state.trackId)?"좋아요에 저장했어요.":"좋아요를 취소했어요.");renderKeep();break;
case"save":toggleList("saved",id);toast(listHas("saved",id)?"내 플레이리스트에 저장했어요.":"플레이리스트에서 제거했어요.");renderKeep();break;
case"follow":toggleList("following",id);toast(listHas("following",id)?artist(id).name+" 팔로우 완료":artist(id).name+" 팔로우 취소");claimBadge();renderKeep();break;
case"share":modal("share",dataType==="artist"?"artist:"+id:id||state.trackId);break;
case"genre":ui.genre=id;renderKeep();break;
case"mood":ui.mood=id;ui.dropIndex=0;renderKeep();break;
case"next-drop":ui.dropIndex++;renderKeep();toast("새로운 아티스트를 발견했어요.");break;
case"claim-badge":{if(earnedSteps().every(Boolean)){claimBadge();modal("badge")}else toast("미션 3개를 완료하면 배지를 받을 수 있어요.");break}
case"modal":modal(id);break;
case"close-modal":closeModal();break;
case"copy-share":copyShare(id);break;
case"native-share":nativeShare(id);break;
default:break;
}}
function initEvents(){
document.addEventListener("click",e=>{
 if(e.target.id==="modal-backdrop"){closeModal();return}
 const route=e.target.closest("[data-route]");if(route){e.preventDefault();closeModal();ui.searchOpen=false;goto(route.dataset.route);return}
 const act=e.target.closest("[data-action]");if(act){e.preventDefault();action(act);return}
});
document.addEventListener("submit",e=>{if(e.target.id==="submission-form"){e.preventDefault();submitForm(e.target)}});
document.addEventListener("input",e=>{
 if(e.target.id==="global-search"){ui.searchValue=e.target.value;ui.searchOpen=true;renderSuggestions()}
 if(e.target.id==="player-seek"){seekTo(e.target.value)}
 if(e.target.id==="volume-range"){state.volume=Number(e.target.value);if(gain)gain.gain.value=state.volume/100*.4;e.target.style.setProperty("--progress",state.volume+"%");persist()}
});
document.addEventListener("keydown",e=>{
 if(e.key==="Escape"){if(ui.modal)closeModal();ui.searchOpen=false;$("#search-menu")?.classList.remove("show")}
 if(e.key==="/"&&!["INPUT","TEXTAREA"].includes(document.activeElement?.tagName)){e.preventDefault();$("#global-search")?.focus()}
 if(e.key==="Enter"&&document.activeElement?.id==="global-search"){e.preventDefault();const q=ui.searchValue.trim();if(q)goto("search?q="+encodeURIComponent(q));ui.searchOpen=false;document.activeElement.blur()}
 if(e.code==="Space"&&!["INPUT","TEXTAREA","BUTTON","SELECT"].includes(document.activeElement?.tagName)&&!ui.modal){e.preventDefault();setPlaying(!ui.playing)}
});
document.addEventListener("focusin",e=>{if(e.target.id==="global-search"){ui.searchOpen=true;renderSuggestions()}});
window.addEventListener("hashchange",()=>{ui.searchOpen=false;render(true)});
document.addEventListener("visibilitychange",()=>{if(document.hidden&&ui.playing)setPlaying(false)});
}
if(!location.hash)history.replaceState(null,"",location.pathname+location.search+"#/discover");
render(true);initEvents();requestAnimationFrame(tick);
